package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.media.*;import java.io.*;import java.util.*;
/** Test-only instrumentation, compiled in a separate disposable checkout. */
public class Stage33Instrumentation extends Instrumentation{
 void check(boolean b,String why){if(!b)throw new AssertionError(why);}void note(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(0,b);}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  Context c=getTargetContext();Semilla language=OwnBrain.load(c);CreatorSession creator=new CreatorSession();SceneDraft tony=creator.apply(language,"crea a Tony una banana detective con sobretodo",null).commit;
  SceneDraft draft=creator.apply(language,"Tony baila mientras entra el pepino y despues el pepino le entrega una caja a Tony y ambos se sorprenden",tony).commit;check(draft!=null&&draft.actions.size()==7,"complete executable plan");draft.sound=true;
  long start=System.nanoTime();NeuralSprites.Batch batch=NeuralSprites.prepare(c,draft,0);note("PREPARE_MS "+(System.nanoTime()-start)/1000000);check(batch.images.size()==2&&batch.objects.size()==1,"all scene participants generated");check(batch.views.get("banana").length==4&&batch.views.get("banana")[3].getWidth()==128,"own front/profile/back views");
  Scene scene=new Scene(draft);scene.setSequence(false);scene.setNeural(batch);check(scene.viewAt("banana",.7f)==1&&scene.viewAt("pepino",.7f)==2,"mutual gaze");check(ObjectTransfer.at(draft,"caja",1,4).owner().equals("banana"),"final holder");
  File dir=c.getExternalFilesDir(null);Motion motion=new Motion(c.getAssets().open("motion.bin"));Bitmap bmp=Bitmap.createBitmap(384,384,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bmp);float[] moments={.12f,.4f,.625f,.9f};for(int i=0;i<moments.length;i++){scene.draw(canvas,384,motion,moments[i]);try(FileOutputStream out=new FileOutputStream(new File(dir,"stage33-frame-"+i+".png"))){bmp.compress(Bitmap.CompressFormat.PNG,100,out);}}
  SceneDraft.Actor bare=new SceneDraft.Actor("banana",50);Bitmap base=NeuralSprites.design(c,bare,0);bare.look="sobretodo";Bitmap coat=NeuralSprites.design(c,bare,0);for(int y=80;y<96;y++)for(int x=60;x<80;x++)check(base.getPixel(x,y)==coat.getPixel(x,y),"protected face pixels");Set<Integer> colors=new HashSet<>();for(int y=0;y<128;y++)for(int x=0;x<128;x++)if((base.getPixel(x,y)>>>24)>240)colors.add(base.getPixel(x,y)&0xffffff);note("OPAQUE_NEURAL_COLORS "+colors.size());
  bare.view="back";Bitmap back=NeuralSprites.design(c,bare,0);check(!back.sameAs(coat),"different learned back view");
  File ref=new File(dir,"reference.png");try(FileOutputStream out=new FileOutputStream(ref)){base.compress(Bitmap.CompressFormat.PNG,100,out);}Bitmap imported=ReferenceImage.importBitmap(c,android.net.Uri.fromFile(ref),false);try(FileOutputStream out=c.openFileOutput("ref_stage33.png",0)){imported.compress(Bitmap.CompressFormat.PNG,100,out);}SceneDraft locked=draft.copy();locked.get("banana").reference="ref_stage33";NeuralSprites.Batch refBatch=NeuralSprites.prepare(c,locked,0);check(refBatch.views.get("banana")[0].sameAs(refBatch.views.get("banana")[3])&&!refBatch.rigs.containsKey("banana"),"reference remains locked");
  CreatorMemory.save(c,new CreatorSession(),draft);SceneLibrary.save(c,"entrega",draft);SceneDraft persisted=SceneLibrary.apply(c,"abri escena entrega",null).scene;check(persisted.recipient(3).equals("banana")&&persisted.props.get(0).holder.equals("pepino"),"persistence");
  VideoExporter.Monitor monitor=new VideoExporter.Monitor(){public boolean cancelled(){return false;}public void progress(int frame,int total){}};File mp4=new File(dir,"stage33-demo.mp4");VideoExporter.write(mp4,scene,motion,scene.frames(),monitor);verify(mp4,scene.frames());note("MP4_H264_AAC_OK frames="+scene.frames());
  BananaTransformer chat=TransformerBrain.load(c);String answer=chat.generate("sos independiente","","").text;check(answer.contains("propios")&&answer.contains("preentrenado"),"own local chat");note("OWN_CHAT33 "+answer);
  note("OWN_VISION "+OwnVision.describe(c,base));result.putString("stream","PASS STAGE33 Android planning, views, protected face, reference, transfer, MP4 AV, persistence and own Chat33.\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));result.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,result);}}
 void verify(File file,int frames)throws Exception{MediaExtractor e=new MediaExtractor();try{e.setDataSource(file.getAbsolutePath());check(e.getTrackCount()==2,"AV tracks");for(int track=0;track<2;track++){String mime=e.getTrackFormat(track).getString(MediaFormat.KEY_MIME);e.selectTrack(track);e.seekTo(0,MediaExtractor.SEEK_TO_CLOSEST_SYNC);int count=0;long last=-1;while(e.getSampleTime()>=0){check(e.getSampleTime()>=last,"monotonic PTS");last=e.getSampleTime();count++;e.advance();}e.unselectTrack(track);check(mime.startsWith("video")?count==frames:count>1,"sample count");}}finally{e.release();}}
}
